head.script:
scwin.onpageload = function() {
    scwin.data1 = [
        "1", "A", 1, 2, 3,
        "1", "A", 2, 2, 3,
        "1", "A", 3, 2, 3,
        "0", "B", 4, 2, 3,
        "0", "C", 5, 2, 3,
        "1", "A", 6, 2, 3,
        "0", "B", 7, 2, 3,
        "1", "A", 30, 2, 3
    ];
    dataList1.setData(scwin.data1.slice(0));
    dataList1.sort("col3", 0);
}
scwin.grid1_ongroupby = function(options) {
    options.closeGroup = true;
    options.rowNumHeader = {
        inputType: 'expression',
        expression: 'toggle() + depthStr() + "    [ " + count() + " 건 ]  "',
        align: 'left',
        colSpan: 5
    };
    options.rowNumFooter = {
        colSpan: 3
    };
    options.rowStatusFooter = {
        value: '합계'
    };
    options.groupbyHeader = [{
        colSpan: "3",
        inputType: "expression",
        expression: 'toggle() + depthStr() + "    [ " + count() + " 건 ]  "',
        align: "left"
    }]
    options.groupbyFooter = [{
            inputType: 'expression',
            expression: 'SUM("col3")'
        },
        {
            inpputType: "text",
            value: "footer"
        }
    ];
    this.groupby(options);
}
scwin.grid1_oncellclick = function(row, col) {
    var rrowIdx = dataList1.getRealRowIndex(row);
    //				console.log("===================================");
    //				console.log("row:: " + row );
    //				console.log("realRowIndex :: " + rrowIdx);
    //				console.log("realRowGetCellData :: " + dataList1.getCellData(rrowIdx , 'col3'));
    //				console.log("getCellData ::"  + dataList1.getCellData(row , "col3"));
    //				console.log("getCellALLData ::"  + dataList1.getCellAllData(row , "col3"));
    //				console.log("getCellRealRowAllData ::"  + dataList1.getCellAllData(rrowIdx , "col3"));
    console.log('row' + row + ' , col' + col);
    console.log('colID :: ' + grid1.getColumnID(col));
    //				console.log("getCellData(row , col) : " + dataList1.getCellData(row, col));
}
scwin.trigger3_onclick = function(e) {
    scwin.onpageload();
};
scwin.trigger4_onclick = function(e) {
    dataList1.removeRows(dataList1.getMatchedIndex('col2', '1'));
};
scwin.checkFilter = function(text1) {
    var arr = WebSquare.wUnit.getJq(".w2grid_customFilter_list_listColumn_text");
    var string = "";
    for (i = 1; i < arr.length; i++) {
        string = string + arr[i].innerText;
    }
    return string.indexOf(text1) == -1;
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 1. 샘플실행 후 '금액'항목의 필터리스트를 클릭하고 'A'로 필터링한다.
    //1. After running the sample, click the filter list in the 'Amount' item and filter it by 'A'.
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grid1_column19_filter').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grid1_customFilter_list').querySelectorAll('div')[1].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grid1_customFilter_list').querySelectorAll('div')[2].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify step 1. '금액'항목이 'A'로 필터링되어진다.
    //1. The 'Amount' item is filtered to 'A'.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('grid1_cell_0_1').innerText == 'A'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. 'delete'버튼을 클릭한다.
    //2. Click the 'delete' button.
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('grid1_column19_filter').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger4').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('grid1_column19_filter').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify step 2. 'A'로 필터링되어진 데이터가 삭제되어진다.
    //2. The data filtered by 'A' is deleted.
    WebSquare.wUnit.addCommand("assert", "scwin.checkFilter('A')", "true");
    //Test step 3. '금액'항목의 필터링을 해제('전체선택' 체크)한다.
    //3. Un-filter the 'Amount' item (check 'Select All').
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grid1_customFilter_list').querySelectorAll('div')[1].click()");
    //Verify step 3. 'A'값을 제외한 나머지 값들이 보여진다.(이전에는 삭제한 'A'값의 셀이 남아서 보여짐)
    //3. The remaining values ​​except for the 'A' value are displayed (Previously, the deleted cell of 'A' value remains and is shown)
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.grid_body_row').not('.w2grid_hidedRow').length == 3", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
